# Database update impact analysis: Signature Renaming Ripples
graph = {"the renaming": "ripples to queries and kin".split(";")}
blast, frontier = set(), ["the renaming"]
while frontier:
    n = frontier.pop()
    for m in graph.get(n, []):
        if m not in blast:
            blast.add(m); frontier.append(m)
print("change:", "the renaming")
print("blast radius:", sorted(blast) or "none")
print("assessment:", "ripples charted, none surprised")

